<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nuevo arqueo</title><style>body{font:15px Arial;background:#f1f5fa;color:#173354;margin:0}.wrap{max-width:980px;margin:25px auto;padding:20px}.panel{background:white;padding:25px;border-radius:12px;margin:20px 0;box-shadow:0 2px 14px #142d4714}h1,h2{color:#10345c}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #e3e9f1;text-align:left}input[type=number],textarea{padding:10px;border:1px solid #aabbd0;border-radius:7px;box-sizing:border-box;width:100%}input[type=checkbox]{width:auto}button{background:#0e5799;color:white;border:0;border-radius:8px;padding:14px 22px;font-weight:bold;cursor:pointer}.sum{font-size:20px;font-weight:bold}.error{color:#a02020}.muted{color:#64768c}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><p><a href="{{route('receptor.arqueos.index')}}">← Mis arqueos</a></p><h1>Arqueo ordinario del receptor</h1><p><strong>Agencia:</strong> {{ $jornada->agencia?->nombre }} · <strong>Ventanilla:</strong> {{ $jornada->ventanilla?->codigo }} · <strong>Turno:</strong> {{ $jornada->turno?->nombre }} · <strong>Fecha:</strong> {{ $jornada->fecha_operativa?->format('d/m/Y') }}</p>@if($errors->any())<div class="panel error" role="alert"><strong>Revise los datos:</strong><ul>@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif<form method="post" action="{{route('receptor.arqueos.store',$jornada->id)}}" id="arqueo-form">@csrf<div class="grid"><section class="panel"><h2>Billetes</h2><table><thead><tr><th>Denominación</th><th>Cantidad</th><th>Subtotal</th></tr></thead><tbody>@foreach($billetes as $v)<tr><td>Q {{number_format($v,2)}}</td><td><input class="denom" type="number" min="0" max="10000000" step="1" name="billetes[{{$v}}]" value="{{old('billetes.'.$v,0)}}" data-centavos="{{$v*100}}" required></td><td class="subtotal">Q 0.00</td></tr>@endforeach</tbody></table></section><section class="panel"><h2>Monedas</h2><table><thead><tr><th>Denominación</th><th>Cantidad</th><th>Subtotal</th></tr></thead><tbody>@foreach($monedas as $v)<tr><td>Q {{$v}}</td><td><input class="denom" type="number" min="0" max="10000000" step="1" name="monedas[{{$v}}]" value="{{old('monedas.'.$v,0)}}" data-centavos="{{(int)round((float)$v*100)}}" required></td><td class="subtotal">Q 0.00</td></tr>@endforeach</tbody></table></section></div><section class="panel"><h2>Comparación del efectivo</h2><p>Total contado: <span class="sum" id="total">Q 0.00</span></p><label for="corte">Monto del corte bancario (Q)</label><input type="number" id="corte" name="total_corte" min="0" max="999999999999.99" step="0.01" value="{{old('total_corte','0.00')}}" required><p>Diferencia (contado − corte): <span class="sum" id="diferencia">Q 0.00</span></p><label for="justificacion">Justificación de diferencias</label><textarea id="justificacion" name="justificacion_diferencia" rows="3" maxlength="2000">{{old('justificacion_diferencia')}}</textarea><p class="muted">Obligatoria cuando exista sobrante o faltante.</p><label for="observaciones">Observaciones</label><textarea id="observaciones" name="observaciones" rows="3" maxlength="5000">{{old('observaciones')}}</textarea></section><section class="panel"><h2>Confirmación de firma electrónica</h2><p>Al confirmar, declara que revisó los importes y que el arqueo quedará firmado, sin posibilidad de editar sus montos.</p><label><input type="checkbox" name="confirmar_firma" value="1" required {{old('confirmar_firma')?'checked':''}}> Confirmo que los datos del arqueo son correctos y autorizo mi firma electrónica.</label><p><button type="submit" id="enviar">Firmar y finalizar arqueo</button></p></section></form></main><script>const fmt=n=>'Q '+(n/100).toLocaleString('es-GT',{minimumFractionDigits:2,maximumFractionDigits:2});function calc(){let total=0;document.querySelectorAll('.denom').forEach(el=>{const cant=Math.max(0,Math.trunc(Number(el.value)||0));const subtotal=cant*Number(el.dataset.centavos);el.closest('tr').querySelector('.subtotal').textContent=fmt(subtotal);total+=subtotal});const corte=Math.round((Number(document.getElementById('corte').value)||0)*100);document.getElementById('total').textContent=fmt(total);document.getElementById('diferencia').textContent=(total-corte<0?'-':'')+fmt(Math.abs(total-corte));document.getElementById('justificacion').required=total!==corte}document.querySelectorAll('.denom,#corte').forEach(el=>el.addEventListener('input',calc));calc();document.getElementById('arqueo-form').addEventListener('submit',function(e){if(!confirm('¿Confirma la firma definitiva del arqueo?')){e.preventDefault();return}document.getElementById('enviar').disabled=true});</script></body></html>